import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  IconButton,
  Menu,
  MenuItem,
  Avatar,
  ListItemIcon,
  ListItemText,
  Button,
  Box,
  Badge,
} from '@mui/material';
import { useLocation, Link, useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import PersonIcon from '@mui/icons-material/Person';
import LoginIcon from '@mui/icons-material/Login';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import { FaHome, FaShoppingCart, FaCashRegister, FaUserShield } from 'react-icons/fa';
import { logout } from '../features/authSlice';
import './Navbar.css';

const Navbar = () => {
  const [anchorEl, setAnchorEl] = useState(null);
  const navigate = useNavigate();
  const location = useLocation();
  const cartCount = useSelector(state => state.cart.items.length);
  const { isAuthenticated, role } = useSelector(state => state.auth);
  const isAdmin = role === 'admin';
  const dispatch = useDispatch();

  const isActive = (path) => location.pathname === path;

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogin = () => {
    navigate('/login');
    handleMenuClose();
  };

  const handleRegister = () => {
    navigate('/register');
    handleMenuClose();
  };

  const handleLogout = () => {
    dispatch(logout());
    handleMenuClose();
    navigate('/');
  };

  return (
    <AppBar position="static" sx={{ backgroundColor: 'primary.main' }}>
      <Toolbar sx={{ justifyContent: 'space-between' }}>
        <nav className="navbar">
          <Link to="/" className={isActive('/') ? 'active' : ''}>
            <FaHome />
            <span>Home</span>
          </Link>
          <Link to="/cart" className={isActive('/cart') ? 'active' : ''}>
            <FaShoppingCart />
            <span>Cart ({cartCount})</span>
          </Link>
          <Link to="/checkout" className={isActive('/checkout') ? 'active' : ''}>
            <FaCashRegister />
            <span>Checkout</span>
          </Link>
          {isAuthenticated && isAdmin && (
            <Link to="/admin" className={isActive('/admin') ? 'active' : ''}>
              <FaUserShield />
              <span>Admin Panel</span>
            </Link>
          )}
        </nav>

        {!isAuthenticated && (
          <IconButton
            color="inherit"
            onClick={handleMenuOpen}
            sx={{
              ml: 2,
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.1)',
              },
            }}
          >
            <Avatar sx={{ bgcolor: 'transparent', width: 35, height: 35 }}>
              <PersonIcon />
            </Avatar>
          </IconButton>
        )}

        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleMenuClose}
          PaperProps={{
            sx: {
              mt: 1.5,
              minWidth: 180,
              boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
            },
          }}
        >
          <MenuItem onClick={handleLogin}>
            <ListItemIcon>
              <LoginIcon fontSize="small" />
            </ListItemIcon>
            <ListItemText primary="Login" />
          </MenuItem>
          <MenuItem onClick={handleRegister}>
            <ListItemIcon>
              <PersonAddIcon fontSize="small" />
            </ListItemIcon>
            <ListItemText primary="Register" />
          </MenuItem>
        </Menu>

        {isAuthenticated && (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            {role === 'admin' && (
              <Button
                color="inherit"
                component={Link}
                to="/admin"
                startIcon={<FaUserShield />}
              >
                Admin Panel
              </Button>
            )}
            <IconButton
              onClick={handleMenuOpen}
              color="inherit"
            >
              <Avatar sx={{ width: 32, height: 32 }}>
                <PersonIcon />
              </Avatar>
            </IconButton>
            <Menu
              anchorEl={anchorEl}
              open={Boolean(anchorEl)}
              onClose={handleMenuClose}
            >
              <MenuItem
                component={Link}
                to="/profile"
                onClick={handleMenuClose}
              >
                Profile
              </MenuItem>
              <MenuItem onClick={handleLogout}>Logout</MenuItem>
            </Menu>
          </Box>
        )}
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
